CREATE TABLE payees (id TEXT PRIMARY KEY NOT NULL, budget_id TEXT NOT NULL, name TEXT NOT NULL,
  hidden INTEGER NOT NULL DEFAULT 0, system TEXT, created_at TEXT NOT NULL, updated_at TEXT NOT NULL,
  deleted_at TEXT);
CREATE UNIQUE INDEX payees_budget_name ON payees(budget_id, name) WHERE deleted_at IS NULL AND system IS NULL;
CREATE UNIQUE INDEX payees_budget_system ON payees(budget_id, system) WHERE deleted_at IS NULL AND system IS NOT NULL;
ALTER TABLE transactions ADD COLUMN payee_id TEXT;
CREATE INDEX transactions_payee ON transactions(payee_id);
INSERT INTO payees (id, budget_id, name, hidden, system, created_at, updated_at, deleted_at) SELECT lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)),2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)),2) || '-' || hex(randomblob(6))), t.budget_id, 'Starting Balance', 0, 'starting_balance', min(t.created_at), min(t.created_at), NULL FROM transactions t WHERE t.payee_name = 'Starting Balance' AND NOT EXISTS (SELECT 1 FROM payees p WHERE p.budget_id = t.budget_id AND p.system = 'starting_balance' AND p.deleted_at IS NULL) GROUP BY t.budget_id;
INSERT INTO payees (id, budget_id, name, hidden, system, created_at, updated_at, deleted_at) SELECT lower(hex(randomblob(4)) || '-' || hex(randomblob(2)) || '-4' || substr(hex(randomblob(2)),2) || '-' || substr('89ab', 1 + (abs(random()) % 4), 1) || substr(hex(randomblob(2)),2) || '-' || hex(randomblob(6))), t.budget_id, t.payee_name, 0, NULL, min(t.created_at), min(t.created_at), NULL FROM transactions t WHERE t.payee_name IS NOT NULL AND trim(t.payee_name) <> '' AND t.payee_name <> 'Starting Balance' AND NOT EXISTS (SELECT 1 FROM payees p WHERE p.budget_id = t.budget_id AND p.name = t.payee_name AND p.system IS NULL AND p.deleted_at IS NULL) GROUP BY t.budget_id, t.payee_name;
UPDATE transactions SET payee_id = (SELECT p.id FROM payees p WHERE p.budget_id = transactions.budget_id AND p.deleted_at IS NULL AND ((transactions.payee_name = 'Starting Balance' AND p.system = 'starting_balance') OR (transactions.payee_name <> 'Starting Balance' AND p.system IS NULL AND p.name = transactions.payee_name))) WHERE payee_id IS NULL AND payee_name IS NOT NULL;
